// Hardware FMA when the target has it; otherwise a separate multiply/add.
#[inline(always)]
fn fma(a: Float, b: Float, c: Float) -> Float {
    #[cfg(target_feature = "fma")]
    {
        a.mul_add(b, c)
    }
    #[cfg(not(target_feature = "fma"))]
    {
        a * b + c
    }
}

// Grouped powers (Estrin): short dependency chains for these latency-bound fits.
// Spell out the fixed 9/12-term trees: LLVM retains loops, stack traffic and
// bounds checks in the generic array reduction. Keep its grouping and FMA
// operations unchanged so both precision lanes retain the same result bits.
#[inline(always)]
fn estrin<const N: usize>(p: &[Float; N], t: Float) -> Float {
    const { assert!(N == 9 || N == 12) };
    let a0 = fma(p[1], t, p[0]);
    let a1 = fma(p[3], t, p[2]);
    let a2 = if p[5] == 0.0 {
        p[4]
    } else {
        fma(p[5], t, p[4])
    };
    let a3 = fma(p[7], t, p[6]);
    let a4 = if N == 9 || p[9] == 0.0 {
        p[8]
    } else {
        fma(p[9], t, p[8])
    };
    let t2 = t * t;
    let b0 = fma(a1, t2, a0);
    let b1 = if p[6] == 0.0 && p[7] == 0.0 {
        a2
    } else {
        fma(a3, t2, a2)
    };
    let b2 = if N == 9 || (p[10] == 0.0 && p[11] == 0.0) {
        a4
    } else {
        fma(fma(p[11], t, p[10]), t2, a4)
    };
    let t4 = t2 * t2;
    let c0 = fma(b1, t4, b0);
    let t8 = t4 * t4;
    if p[8] == 0.0 && (N == 9 || (p[9] == 0.0 && p[10] == 0.0 && p[11] == 0.0)) {
        c0
    } else {
        fma(b2, t8, c0)
    }
}

// x^(5/12) for normal x in (0, 1]: x = m·2^e with e = 12q + r, so
// x^(5/12) = m^(5/12) · 2^(5q) · 2^(5r/12). Degree-5 Chebyshev-derived
// polynomial for m in [1, 2): 1.8e-6 relative, about 1.9e-6 encoded.
// Each lane splits its own float format: the f32 lane is pure f32.
const TWELFTHS: [f64; 12] = [
    1.0,
    1.3348398541700344,
    1.7817974362806785,
    2.378414230005442,
    3.174802103936399,
    4.237852377437181,
    5.656854249492381,
    7.550994501453547,
    10.079368399158986,
    13.454342644059432,
    17.959392772949972,
    23.9729132300269,
];
#[inline(always)]
fn mantissa_power(m: Float) -> Float {
    let t = 2.0 * m - 3.0;
    let t2 = t * t;
    (1.1840522979550885 + 0.16445223215860819 * t)
        + t2 * (-0.015965263486395525 + 0.0028065866056053617 * t)
        + t2 * t2 * (-0.0006657143993239837 + 0.00016073400297855756 * t)
}
#[inline(always)]
fn pow_5_12(x: Float) -> Float {
    if SINGLE {
        let bits = (x as f32).to_bits();
        let e = ((bits >> 23) as i32) - 127;
        let m = f32::from_bits((bits & 0x007f_ffff) | 0x3f80_0000) as Float;
        let (q, r) = (e.div_euclid(12), e.rem_euclid(12));
        let scale = f32::from_bits(((127 + 5 * q) as u32) << 23) as Float;
        mantissa_power(m) * (scale * const { narrow(TWELFTHS) }[r as usize])
    } else {
        let bits = (x as f64).to_bits();
        let e = ((bits >> 52) as i64) - 1023;
        let m = f64::from_bits((bits & 0x000f_ffff_ffff_ffff) | 0x3ff0_0000_0000_0000) as Float;
        let (q, r) = (e.div_euclid(12), e.rem_euclid(12));
        let scale = f64::from_bits(((1023 + 5 * q) as u64) << 52) * TWELFTHS[r as usize];
        mantissa_power(m) * scale as Float
    }
}
#[inline(always)]
fn encode_fast<G: DualrayFastData>(x: Float) -> Float {
    let x = x.clamp(0.0, 1.0);
    let y = if G::ID == SpaceId::Rec2020 {
        if x < Float::MIN_POSITIVE {
            0.0
        } else {
            pow_5_12(x)
        }
    } else if x <= 0.0031308 {
        12.92 * x
    } else {
        1.055 * pow_5_12(x) - 0.055
    };
    // The polynomial's error can exceed one just below x = 1.
    y.min(1.0)
}

// Which path mapped a color (diagnostics; `map` discards it).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Path {
    Endpoint,
    Lower,
    Inside,
    MarginBand,
    Upper,
    UpperRetry,
    Search,
}

// Why the shortcut declined.
enum Decline {
    // A hue the fits do not cover (a blue-fold window).
    Uncovered,
    // Chroma below the fitted ratio plus margin: inside, the margin band, or
    // above the cusp.
    BelowRatio {
        sector: usize,
        t: Float,
        root: Float,
    },
    // Beyond the lower boundary and above the cusp: outside via an upper face.
    AboveCusp {
        sector: usize,
        root: Float,
        g: [Float; 2],
    },
}

// Nonzero channels of each sector, in increasing order; the third is zero.
const NONZERO: [[usize; 2]; 3] = [[0, 1], [1, 2], [0, 2]];

pub(crate) struct DualrayFast<G: DualrayFastData, const FAST_ENCODE: bool = false>(
    std::marker::PhantomData<G>,
);

impl<G: DualrayFastData, const FAST_ENCODE: bool> DualrayFast<G, FAST_ENCODE> {
    pub(crate) fn new() -> Self {
        Self(std::marker::PhantomData)
    }

    #[inline(always)]
    fn encode(x: Float) -> Float {
        if FAST_ENCODE {
            encode_fast::<G>(x)
        } else {
            G::Transfer::encode_clamped(x)
        }
    }

    // Lower-face output: the sector's zero channel and two fitted channels.
    #[inline(always)]
    fn lower(sector: usize, x: [Float; 2], out: &mut [Float; 3]) {
        *out = [0.0; 3];
        let [i, j] = NONZERO[sector];
        out[i] = Self::encode(x[0]);
        out[j] = Self::encode(x[1]);
    }

    // The shortcut, at a hue in [0, 360).
    #[inline(always)]
    fn shortcut(l: Float, c: Float, h: Float, out: &mut [Float; 3]) -> Result<(), Decline> {
        if h >= G::BLUE_START && h < G::RED_START {
            Self::shortcut_sector::<0>(l, c, h, out)
        } else if h >= G::RED_START && h < G::RED_END {
            Self::shortcut_sector::<1>(l, c, (G::RED_FOLD - h).sqrt(), out)
        } else if h > G::GREEN_START && h < 360.0 {
            Self::shortcut_sector::<2>(l, c, h, out)
        } else if h >= 0.0 && h < G::BLUE_START {
            Self::shortcut_sector::<2>(l, c, h + 360.0, out)
        } else {
            Err(Decline::Uncovered)
        }
    }

    #[inline(always)]
    fn shortcut_sector<const SECTOR: usize>(
        l: Float,
        c: Float,
        v: Float,
        out: &mut [Float; 3],
    ) -> Result<(), Decline> {
        let sector = SECTOR;
        let t = fma(G::SCALE[sector], v, G::OFFSET[sector]);
        let root = estrin(&G::U[sector], t);
        if !(c >= (root + G::MARGIN[sector]) * l) {
            return Err(Decline::BelowRatio { sector, t, root });
        }
        let l3 = l * l * l;
        let g = [estrin(&G::G0[sector], t), estrin(&G::G1[sector], t)];
        if !(l3 * g[0] <= 1.0 && l3 * g[1] <= 1.0) {
            return Err(Decline::AboveCusp { sector, root, g });
        }
        Self::lower(sector, g.map(|x| l3 * x), out);
        Ok(())
    }

    // The exact first exit (Dualray's search) for colors the fast paths do
    // not cover.
    fn search(l: Float, c: Float, h: Float, out: &mut [Float; 3]) -> Path {
        let (b, a) = (h * (PI / 180.0)).sin_cos();
        let inv_l = 1.0 / l;
        let target = inv_l * inv_l * inv_l;
        let limit = (c * inv_l).max(0.0);
        *out = search::<G>(
            ray_rows::<G>(a, b),
            h,
            l * l * l,
            target,
            limit,
            Self::encode,
        );
        Path::Search
    }

    // The canonical conversion, at the authored hue: true (with the
    // conversion written) when it is in gamut.
    #[inline(always)]
    fn inside(l: Float, c: Float, h: Float, out: &mut [Float; 3]) -> bool {
        let rgb = super::color::Oklch::from([l, c, h])
            .to_oklab()
            .to_linear_rgb::<G>();
        if rgb.in_gamut() {
            *out = rgb.encode_clamped().channels;
        }
        rgb.in_gamut()
    }

    pub(crate) fn map_path(oklch: &[Float; 3], out: &mut [Float; 3]) -> Path {
        let [l, c, h] = *oklch;
        if !(l > 0.0 && l < 1.0) {
            *out = [if l >= 1.0 { 1.0 } else { 0.0 }; 3];
            return Path::Endpoint;
        }
        let c = c.max(0.0);
        let in_range = h >= 0.0 && h < 360.0;
        let hue = if in_range { h } else { h.rem_euclid(360.0) };
        // The fits need the reduced hue, but the canonical conversion uses
        // the authored one, and for a large f64 hue the two round to
        // directions degrees apart. Check membership first, so the shortcut
        // cannot claim a canonically in-gamut color.
        if !in_range && Self::inside(l, c, h, out) {
            return Path::Inside;
        }
        let decline = match Self::shortcut(l, c, hue, out) {
            Ok(()) => return Path::Lower,
            Err(decline) => decline,
        };
        // Above the cusp beyond the lower boundary is always out of gamut.
        if in_range && !matches!(decline, Decline::AboveCusp { .. }) && Self::inside(l, c, h, out) {
            return Path::Inside;
        }
        let (sector, root, g) = match decline {
            Decline::Uncovered => return Self::search(l, c, hue, out),
            Decline::AboveCusp { sector, root, g } => (sector, root, g),
            Decline::BelowRatio { sector, t, root } => {
                let g = [estrin(&G::G0[sector], t), estrin(&G::G1[sector], t)];
                (sector, root, g)
            }
        };
        let l3 = l * l * l;
        if l3 * g[0] <= 1.0 && l3 * g[1] <= 1.0 {
            // Out of gamut below the cusp (the margin band): the lower face.
            // For an out-of-range hue, "out of gamut" was decided at the
            // authored direction; search the reduced one instead.
            if !in_range {
                return Self::search(l, c, hue, out);
            }
            Self::lower(sector, g.map(|x| l3 * x), out);
            return Path::MarginBand;
        }
        // Above the cusp: the chord from the fitted lower root to the brighter
        // lower channel's crossing, refined by Dualray's upper solve.
        let brighter = (g[1] > g[0]) as usize;
        let face = NONZERO[sector][brighter];
        let (b, a) = (hue * (PI / 180.0)).sin_cos();
        let inv_l = 1.0 / l;
        let target = inv_l * inv_l * inv_l;
        let seed = root * (target - 1.0) / (g[brighter] - 1.0);
        let Some((_, exit, values)) =
            upper(ray_rows::<G>(a, b), target, seed, face, c * inv_l, false)
        else {
            return Self::search(l, c, hue, out);
        };
        *out = std::array::from_fn(|k| {
            if k == exit {
                1.0
            } else {
                Self::encode(l3 * values[k])
            }
        });
        if exit == face {
            Path::Upper
        } else {
            Path::UpperRetry
        }
    }

    // Diagnostics: the path a color takes.
    #[allow(dead_code)] // Used by the dualray-fast example.
    pub(crate) fn path(oklch: &[Float; 3]) -> Path {
        Self::map_path(oklch, &mut [0.0; 3])
    }

    #[inline(always)]
    pub(crate) fn map(&mut self, oklch: &[Float; 3], out: &mut [Float; 3]) {
        Self::map_path(oklch, out);
    }

    // The canonical precheck is part of the method: both modes are identical.
    #[inline(always)]
    pub(crate) fn map_with_in_gamut_check(&mut self, oklch: &[Float; 3], out: &mut [Float; 3]) {
        self.map(oklch, out);
    }
}

// The same method with the polynomial transfer function (separate benchmark row).
pub(crate) type DualrayFastEncode<G> = DualrayFast<G, true>;

#[cfg(test)]
mod tests {
    use super::*;

    // Retain the original reduction as a bitwise compatibility reference.
    // Horner evaluation would change rounding and cannot check this contract.
    fn estrin_loop<const N: usize>(p: &[Float; N], t: Float) -> Float {
        let mut level = [0.0 as Float; 16];
        let mut n = 0;
        let mut i = 0;
        while i < N {
            level[n] = if i + 1 < N {
                fma(p[i + 1], t, p[i])
            } else {
                p[i]
            };
            n += 1;
            i += 2;
        }
        let mut x = t * t;
        while n > 1 {
            let mut j = 0;
            let mut k = 0;
            while j < n {
                level[k] = if j + 1 < n {
                    fma(level[j + 1], x, level[j])
                } else {
                    level[j]
                };
                k += 1;
                j += 2;
            }
            n = k;
            x = x * x;
        }
        level[0]
    }

    #[test]
    fn unrolled_fits_preserve_result_bits() {
        fn check<const N: usize>(p: &[Float; N]) {
            for i in 0..=20_000 {
                let t = i as Float / 10_000.0 - 1.0;
                assert_eq!(
                    estrin(p, t).to_bits(),
                    estrin_loop(p, t).to_bits(),
                    "{N}-term fit at t={t}"
                );
            }
        }
        fn gamut<G: DualrayFastData>() {
            for p in G::U {
                check(&p);
            }
            for p in G::G0 {
                check(&p);
            }
            for p in G::G1 {
                check(&p);
            }
        }
        gamut::<Srgb>();
        gamut::<DisplayP3>();
        gamut::<Rec2020>();
    }

    // Out-of-range authored hues: a canonically in-gamut color passes through
    // bit for bit, whatever direction the reduced hue gives the fits.
    fn preserves_in_gamut<G: DualrayFastData>() {
        let mut fast = DualrayFast::<G>::new();
        let hues = [
            -1e300,
            -1e16,
            -720.25,
            -95.947975,
            -0.0,
            360.0,
            1e7,
            1e12,
            10000000000005742.0,
            3.0e38,
            1e300,
        ];
        // Casting to f32 overflows the largest to infinity, outside the domain.
        for h in hues
            .map(|x: f64| x as Float)
            .into_iter()
            .filter(|h| h.is_finite())
        {
            for li in 1..40 {
                for ci in 0..40 {
                    let input = [li as Float / 40.0, ci as Float * 0.01, h];
                    let rgb = super::super::color::Oklch::from(input)
                        .to_oklab()
                        .to_linear_rgb::<G>();
                    let mut out = [0.0; 3];
                    fast.map(&input, &mut out);
                    assert!(
                        out.iter().all(|v| v.is_finite() && (0.0..=1.0).contains(v)),
                        "{input:?}: {out:?}"
                    );
                    if rgb.in_gamut() {
                        assert_eq!(
                            out.map(Float::to_bits),
                            rgb.encode_clamped().channels.map(Float::to_bits),
                            "{} {input:?}",
                            G::DEFINITION.name
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn out_of_range_hues_keep_canonical_in_gamut_colors() {
        preserves_in_gamut::<Srgb>();
        preserves_in_gamut::<DisplayP3>();
        preserves_in_gamut::<Rec2020>();
        // Review reproducer: f64 reduction gives 262 degrees, the canonical
        // direction differs, and the shortcut claimed an in-gamut color.
        if !SINGLE {
            let input = [0.5, 0.3, 10000000000005742.0 as Float];
            let rgb = super::super::color::Oklch::from(input)
                .to_oklab()
                .to_linear_rgb::<DisplayP3>();
            assert!(rgb.in_gamut());
            let mut out = [0.0; 3];
            DualrayFast::<DisplayP3>::new().map(&input, &mut out);
            assert_eq!(out, rgb.encode_clamped().channels);
        }
    }
